export interface LogsLogsAlertsCreateInput {
    /** Human-readable name for this alert. Defaults to 'Untitled alert' on create when omitted. */
    name?: AiObservabilityLlmaReviewQueueUpdateRequestSchema0
    /** Whether the alert is actively being evaluated. Disabling resets the state to not_firing. */
    enabled?: AiObservabilityLlmaEvaluationListRequestSchema1
    /** Filter criteria — subset of LogsViewerFilters. Must contain at least one of: severityLevels (list of severity strings), serviceNames (list of service name strings), or filterGroup (property filter group object). May be empty on draft alerts (enabled=false). */
    filters?: LogsLogsAlertsCreateRequestSchema2
    /** Number of matching log entries that constitutes a threshold breach within the evaluation window. Defaults to 100. Use 0 with the 'above' operator to fire on any matching log. */
    threshold_count?: LogsLogsAlertsCreateRequestSchema22
    /** Whether the alert fires when the count is above or below the threshold.
     *
     * * `above` - Above
     * * `below` - Below */
    threshold_operator?: LogsLogsAlertsCreateRequestSchema23
    /** Time window in minutes over which log entries are counted. Allowed values: 5, 10, 15, 30, 60. */
    window_minutes?: DashboardsDashboardWidgetsBatchAddRequestSchema24
    /** Total number of check periods in the sliding evaluation window for firing (M in N-of-M). */
    evaluation_periods?: LogsLogsAlertsCreateRequestSchema25
    /** How many periods within the evaluation window must breach the threshold to fire (N in N-of-M). */
    datapoints_to_alarm?: LogsLogsAlertsCreateRequestSchema26
    /** Minimum minutes between repeated notifications after the alert fires. 0 means no cooldown. */
    cooldown_minutes?: LogsLogsAlertsCreateRequestSchema27
    /** Blocked local time windows when the alert must not run. Times use the project timezone. Null disables quiet hours. */
    schedule_restriction?: LogsLogsAlertsCreateRequestSchema28 | null
    /** ISO 8601 timestamp until which the alert is snoozed. Set to null to unsnooze. */
    snooze_until?: LogsLogsAlertsCreateRequestSchema30 | null
}

