/**
 * HogQL Query Options are automatically set per team. However, they can be overridden in the query.
 */
export interface QueriesSqlRequestHogQLQueryModifiers {
    bounceRateDurationSeconds?: number
    bounceRatePageViewMode?: QueriesSqlRequestHogQLQueryModifiersBounceRatePageViewMode
    convertToProjectTimezone?: boolean
    /** Do not treat a missing user agent as automation on cookieless events. Positive bot signals and custom project rules still apply. Resolved server-side; not intended to be set by clients. */
    cookielessTrafficIsRegular?: boolean | null
    customBotDefinitions?: QueriesSqlRequestCustomBotRule[]
    customChannelTypeRules?: QueriesSqlRequestCustomChannelRule[]
    dataWarehouseEventsModifiers?: QueriesSqlRequestDataWarehouseEventsModifier[]
    debug?: boolean
    /** If these are provided, the query will fail if these skip indexes are not used */
    forceClickhouseDataSkippingIndexes?: string[]
    formatCsvAllowDoubleQuotes?: boolean
    inCohortVia?: QueriesSqlRequestHogQLQueryModifiersInCohortVia
    inlineCohortCalculation?: QueriesSqlRequestHogQLQueryModifiersInlineCohortCalculation
    materializationMode?: QueriesSqlRequestHogQLQueryModifiersMaterializationMode
    materializedColumnsOptimizationMode?: QueriesSqlRequestHogQLQueryModifiersMaterializedColumnsOptimizationMode
    /** Merge sibling aggregating LEFT JOINs over federated Postgres tables into one UNION ALL join, so their scans overlap */
    mergeFederatedAggregateJoins?: boolean
    optimizeJoinedFilters?: boolean
    optimizeProjections?: boolean
    /** HogQL parser backend; absent → `rust_py_with_cpp_shadow` (rust-py is primary, cpp runs as a sampled shadow). `*_shadow` modes return the primary result and sample-compare against the other parser, reporting divergences without failing the request. The `rust_py_*` modes drive the same hand-rolled Rust parser as `rust_*` but build `posthog.hogql.ast` dataclass instances directly via PyO3, skipping the JSON round-trip. */
    parserMode?: QueriesSqlRequestHogQLQueryModifiersParserMode
    /** Push an `id IN (SELECT person_id FROM <left table> WHERE …)` predicate into the joined persons subquery, so the latest-version lookup only reads persons that the outer query's left-table filters can reach. Applies only to a persons join from the query's own FROM table. */
    personIdPushdown?: boolean
    personsArgMaxVersion?: QueriesSqlRequestHogQLQueryModifiersPersonsArgMaxVersion
    personsJoinMode?: QueriesSqlRequestHogQLQueryModifiersPersonsJoinMode
    personsOnEventsMode?: QueriesSqlRequestHogQLQueryModifiersPersonsOnEventsMode
    propertyGroupsMode?: QueriesSqlRequestHogQLQueryModifiersPropertyGroupsMode
    pushDownPredicates?: boolean
    s3TableUseInvalidColumns?: boolean
    /** Push a `session_id_v7 IN (SELECT … FROM events WHERE …)` predicate into the raw_sessions subquery to limit aggregation to sessions that participate in the outer events filter. */
    sessionIdPushdown?: boolean
    /** Pre-filter raw_sessions aggregation by `session_id_v7 IN (cheap pre-aggregation that only materializes the columns referenced by the outer-WHERE session predicate)`. Useful when the breakdown/SELECT pulls in many session columns (e.g. `$channel_type`) but the filter only references one (e.g. `$entry_current_url`). */
    sessionPropertyPreAggregation?: boolean
    sessionTableVersion?: QueriesSqlRequestHogQLQueryModifiersSessionTableVersion
    sessionsV2JoinMode?: QueriesSqlRequestHogQLQueryModifiersSessionsV2JoinMode
    timings?: boolean
    /** Remove provably redundant casts and nullability wrappers (e.g. `toString(String)`, `assumeNotNull(non_nullable)`, dead `ifNull` fallbacks) using inferred expression types */
    typeAwareCastSimplification?: boolean
    useMaterializedViews?: boolean
    /** Read events from the native JSON events table (`true`) or the legacy events table (`false`). When unset, the project's stored value applies, then the `CLICKHOUSE_HOGQL_USE_NEW_EVENTS_SCHEMA` instance settings. This is an internal rollout switch. PostHog staff set the project value in Django admin and the project settings API ignores it. */
    useNewEventsSchema?: boolean
    usePreaggregatedIntermediateResults?: boolean
    /** Try to automatically convert HogQL queries to use preaggregated tables at the AST level * */
    usePreaggregatedTableTransforms?: boolean
    useWebAnalyticsPreAggregatedTables?: boolean
    /** Serve filters on the stored session-entry attribution properties (`$channel_type`, `$entry_utm_*`, `$entry_referring_domain`) by recomputing the value from the session's first pageview. Resolved server-side; not intended to be set by clients. */
    webAnalyticsFirstPageviewFilters?: boolean
}

